class Solution {
  private static int lcp(String a, String b) {
    int k = 0, m = Math.min(a.length(), b.length());
    while (k < m && a.charAt(k) == b.charAt(k)) k++;
    return k;
  }

  public int[] longestCommonPrefix(String[] words) {
    int n = words.length;
    int[] ans = new int[n];
    if (n <= 2) return ans;
    int[] pair = new int[n - 1];
    for (int i = 0; i + 1 < n; i++) pair[i] = lcp(words[i], words[i + 1]);
    int[] pre = new int[n], suf = new int[n + 1];
    for (int i = 0; i < n - 1; i++) pre[i + 1] = Math.max(pre[i], pair[i]);
    for (int i = n - 2; i >= 0; i--) suf[i] = Math.max(suf[i + 1], pair[i]);
    for (int i = 0; i < n; i++) {
      int best = 0;
      if (i - 1 >= 0) best = Math.max(best, pre[i - 1]);
      if (i + 1 <= n - 2) best = Math.max(best, suf[i + 1]);
      if (i - 1 >= 0 && i + 1 < n) best = Math.max(best, lcp(words[i - 1], words[i + 1]));
      ans[i] = best;
    }
    return ans;
  }
}
